        chainEffects:[{level:'potencial',title:'Pèrdua de frescor i aigua → menor refugi → major exposició biològica',reasoning:'Pot reduir opcions per fauna i vegetació durant episodis extrems.'},{level:'potencial',title:'Desconnexió → refugi aïllat → menor funcionalitat',reasoning:'La qualitat local pot ser insuficient si no hi ha permeabilitat territorial.'}],
