        prioritySectors:[{level:'potencial',category:'Conservació prioritària',description:'Candidats alts o molt alts que coincideixin amb aigua permanent, HIC sensibles i connectivitat.',basis:'Cribratge multivariable.',validation:'Microclima, permanència hídrica i ús biològic.'}],
        managementImplications:[{priority:'P1',action:'Validar i protegir els candidats més robustos.',rationale:'Poden sostenir resiliència durant calor i sequera.',validation:'Sensors, aigua, estructura i fauna.'},{priority:'P2',action:'Reduir alteracions hidrològiques o d’accés demostrades.',rationale:'Manté els processos que generen el refugi.',validation:'Pressió real i resposta.'}],
